export function formatJsonCodeBlock(editor: Editor, element: Element) {
  if (editor.read.view.isReadOnly()) return;

  const blockPath = editor.read.nodes.path(element);

  if (!blockPath) return;

  const block = editor.read.nodes.get(blockPath)?.[0];

  if (
    block !== element ||
    !ElementApi.isElement(block) ||
    block.type !== editor.plugin(CodeBlockPlugin).schema.type ||
    block.language !== 'json' ||
    block.children.length !== 1
  ) {
    return;
  }

  const [child] = block.children;

  if (!NodeApi.isText(child)) return;

  const { text } = child;
  let formatted: string;

  try {
    formatted = JSON.stringify(JSON.parse(text), null, 2);
  } catch {
    return;
  }

  if (formatted === text) return;

  const diff = new DiffMatchPatch().diff_main(text, formatted, false);
  const edits: Array<{ end: number; start: number; text: string }> = [];
  let oldOffset = 0;
  let start: number | null = null;
  let replacement = '';

  for (const [operation, value] of diff) {
    if (operation === DiffOp.Equal) {
      if (start !== null) {
        edits.push({ start, end: oldOffset, text: replacement });
        start = null;
        replacement = '';
      }
      oldOffset += value.length;
    } else if (operation === DiffOp.Delete) {
      start ??= oldOffset;
      oldOffset += value.length;
    } else {
      start ??= oldOffset;
      replacement += value;
    }
  }

  if (start !== null) {
    edits.push({ start, end: oldOffset, text: replacement });
  }

  editor.update((tx) => {
    for (const edit of edits.reverse()) {
      const at = {
        anchor: { path: [...blockPath, 0], offset: edit.start },
        focus: { path: [...blockPath, 0], offset: edit.end },
      };

      if (edit.text) {
        tx.text.insert(edit.text, { at });
      } else {
        tx.text.delete({ at });
      }
    }
  });
}

function CodeBlockCopyButton() {
  const editor = useEditor();
  const element = useElement(CodeBlockPlugin);

  return (
    <CopyButton
      size="icon"
      variant="ghost"
      className="size-6 gap-1 text-xs text-muted-foreground"
      value={() => {
        const path = editor.read.nodes.path(element);

        return path ? editor.read.text.string(path) : '';
      }}
    />
  );
}

function CodeBlockCombobox({
  languageOptions = codeBlockLanguages,
  showLanguageLabel,
}: {
  showLanguageLabel: boolean;
  languageOptions?: Array<{ label: string; value: string }>;
}) {
  const [open, setOpen] = React.useState(false);
  const readOnly = useEditorReadOnly();
  const editor = useEditor();
  const element = useElement(CodeBlockPlugin);
  const value = element.language || 'plaintext';
  const [searchValue, setSearchValue] = React.useState('');

  const items = React.useMemo(
    () =>
      languageOptions.filter(
        (language) =>
          !searchValue ||
          language.label.toLowerCase().includes(searchValue.toLowerCase())
      ),
    [searchValue, languageOptions]
  );

  if (readOnly) {
    if (!showLanguageLabel) return null;

    return <CodeBlockLanguageLabel lang={element.language} />;
  }

  return (
    <FloatingPopover open={open} onOpenChange={setOpen}>
      <FloatingPopoverTrigger>
        <Button
          size="sm"
          variant="ghost"
          className="h-6 justify-between gap-1 px-2 text-xs text-muted-foreground select-none"
          aria-controls="code-block-language-options"
          aria-expanded={open}
          role="combobox"
        >
          {getCodeBlockLanguageLabel(value) ?? 'Plain Text'}
        </Button>
      </FloatingPopoverTrigger>
      <FloatingPopoverContent
        className="w-[200px] p-0"
        id="code-block-language-options"
        onFinalFocus={() => {
          setSearchValue('');
        }}
      >
        <Command shouldFilter={false}>
          <CommandInput
            className="h-9"
            value={searchValue}
            onValueChange={(innerValue) => {
              setSearchValue(innerValue);
            }}
            placeholder="Search language..."
          />
          <CommandEmpty>No language found.</CommandEmpty>

          <CommandList className="h-[344px] overflow-y-auto">
            <CommandGroup>
              {items.map((language) => (
                <CommandItem
                  key={language.label}
                  className="cursor-pointer"
                  value={language.value}
                  onSelect={(innerValue2) => {
                    const path = editor.read.nodes.path(element);

                    if (!path) return;

                    editor
                      .plugin(CodeBlockPlugin)
                      .update.set({ language: innerValue2 }, { at: path });
                    setSearchValue(innerValue2);
                    setOpen(false);
                  }}
                >
                  <Check
                    className={cn(
                      value === language.value ? 'opacity-100' : 'opacity-0'
                    )}
                  />
                  {language.label}
                </CommandItem>
              ))}
            </CommandGroup>
          </CommandList>
        </Command>
      </FloatingPopoverContent>
    </FloatingPopover>
  );
}

function CodeBlockLanguageLabel({ lang }: { lang?: string | null }) {
  const label = getCodeBlockLanguageLabel(lang);

  if (!label) return null;

  return (
    <span className="flex h-6 items-center px-2 text-xs text-muted-foreground select-none">
      {label}
    </span>
  );
}

function CopyButton({
  value,
  ...props
}: { value: (() => string) | string } & Omit<
  React.ComponentProps<typeof Button>,
  'value'
>) {
  const [status, setStatus] = React.useState<
    'idle' | 'copying' | 'copied' | 'failed'
  >('idle');

  React.useEffect(() => {
    if (status !== 'copied') return undefined;

    const timeout = setTimeout(() => {
      setStatus('idle');
    }, 2000);

    return () => {
      clearTimeout(timeout);
    };
  }, [status]);

  return (
    <Button
      disabled={status === 'copying'}
      onClick={async () => {
        setStatus('copying');
        try {
          await navigator.clipboard.writeText(
            typeof value === 'function' ? value() : value
          );
          setStatus('copied');
        } catch {
          setStatus('failed');
        }
      }}
      title={status === 'failed' ? 'Copy failed. Try again.' : 'Copy'}
      {...props}
    >
      <span className="sr-only">
        {status === 'failed' ? 'Copy failed. Try again.' : 'Copy'}
      </span>
      {status === 'copied' ? (
        <CheckIcon className="!size-3" />
      ) : (
        <CopyIcon className="!size-3" />
      )}
    </Button>
  );
}

export const createCodeBlockPlugin = (component: typeof CodeBlockElement) =>
  CodeBlockPlugin.configure({
    component,
    inputRules: [CodeBlockRules.markdown({ on: 'match' })],
    shortcuts: { toggle: { keys: 'mod+alt+8' } },
  });

const lowlight = createCodeBlockLowlight();

export const CodeBlockKit = [
  createCodeBlockPlugin(CodeBlockElement),
  CodeHighlightPlugin.configure({
