    'from',
    'global',
    'if',
    'import',
    'in',
    'is',
    'lambda',
    'match',
    'nonlocal|10',
    'not',
    'or',
    'pass',
    'raise',
    'return',
    'try',
    'while',
    'with',
    'yield',
  ];
  const builtIns = [
    '__import__',
    'abs',
    'all',
    'any',
    'ascii',
    'bin',
    'bool',
    'breakpoint',
    'bytearray',
    'bytes',
    'callable',
    'chr',
    'classmethod',
    'compile',
    'complex',
    'delattr',
    'dict',
    'dir',
    'divmod',
    'enumerate',
    'eval',
    'exec',
    'filter',
    'float',
    'format',
    'frozenset',
    'getattr',
    'globals',
    'hasattr',
    'hash',
    'help',
    'hex',
    'id',
    'input',
    'int',
    'isinstance',
    'issubclass',
    'iter',
    'len',
    'list',
    'locals',
    'map',
    'max',
    'memoryview',
    'min',
    'next',
    'object',
    'oct',
    'open',
    'ord',
    'pow',
    'print',
    'property',
    'range',
    'repr',
    'reversed',
    'round',
    'set',
    'setattr',
    'slice',
    'sorted',
    'staticmethod',
    'str',
    'sum',
    'super',
    'tuple',
    'type',
    'vars',
    'zip',
  ];
  const literals = [
    '__debug__',
    'Ellipsis',
    'False',
    'None',
    'NotImplemented',
    'True',
  ];
  const types = [
    'Any',
    'Callable',
    'Coroutine',
    'Dict',
    'List',
    'Literal',
    'Generic',
    'Optional',
    'Sequence',
    'Set',
    'Tuple',
    'Type',
    'Union',
  ];
  const keywords: NonNullable<HighlightMode['keywords']> = {
    $pattern: String.raw`[A-Za-z]\w+|__\w+__`,
    built_in: builtIns,
    keyword: reservedWords,
    literal: literals,
    type: types,
  };
  const prompt: HighlightMode = {
    begin: /^(>>>|\.\.\.) /,
    className: 'meta',
  };
  const subst: HighlightMode = {
    begin: /\{/,
    className: 'subst',
    end: /\}/,
    illegal: /#/,
    keywords,
  };
  const literalBracket: HighlightMode = {
    begin: /\{\{/,
    relevance: 0,
  };
  const string: HighlightMode = {
    className: 'string',
    contains: [hljs.BACKSLASH_ESCAPE],
    variants: [
      {
        begin: /([uU]|[bB]|[rR]|[bB][rR]|[rR][bB])?'''/,
        contains: [hljs.BACKSLASH_ESCAPE, prompt],
        end: /'''/,
        relevance: 10,
      },
      {
        begin: /([uU]|[bB]|[rR]|[bB][rR]|[rR][bB])?"""/,
        contains: [hljs.BACKSLASH_ESCAPE, prompt],
        end: /"""/,
        relevance: 10,
      },
      {
        begin: /([fF][rR]|[rR][fF]|[fF])'''/,
        contains: [hljs.BACKSLASH_ESCAPE, prompt, literalBracket, subst],
        end: /'''/,
      },
      {
        begin: /([fF][rR]|[rR][fF]|[fF])"""/,
        contains: [hljs.BACKSLASH_ESCAPE, prompt, literalBracket, subst],
        end: /"""/,
      },
      {
        begin: /([uU]|[rR])'/,
        end: /'/,
        relevance: 10,
      },
      {
        begin: /([uU]|[rR])"/,
        end: /"/,
        relevance: 10,
      },
      {
        begin: /([bB]|[bB][rR]|[rR][bB])'/,
        end: /'/,
      },
      {
        begin: /([bB]|[bB][rR]|[rR][bB])"/,
        end: /"/,
      },
      {
        begin: /([fF][rR]|[rR][fF]|[fF])'/,
        contains: [hljs.BACKSLASH_ESCAPE, literalBracket, subst],
        end: /'/,
      },
      {
        begin: /([fF][rR]|[rR][fF]|[fF])"/,
        contains: [hljs.BACKSLASH_ESCAPE, literalBracket, subst],
        end: /"/,
      },
      hljs.APOS_STRING_MODE,
      hljs.QUOTE_STRING_MODE,
    ],
  };
  const digitPart = '[0-9](_?[0-9])*';
  const pointFloat = `(\\b(${digitPart}))?\\.(${digitPart})|\\b(${digitPart})\\.`;
  const number: HighlightMode = {
    className: 'number',
    relevance: 0,
    variants: [
      {
        begin: `(\\b(${digitPart})|(${pointFloat}))[eE][+-]?(${digitPart})[jJ]?\\b`,
      },
      {
        begin: `(${pointFloat})[jJ]?`,
      },
      {
        begin: '\\b([1-9](_?[0-9])*|0+(_?0)*)[lLjJ]?\\b',
      },
      {
        begin: '\\b0[bB](_?[01])+[lL]?\\b',
      },
      {
        begin: '\\b0[oO](_?[0-7])+[lL]?\\b',
      },
      {
        begin: '\\b0[xX](_?[0-9a-fA-F])+[lL]?\\b',
      },
      {
        begin: `\\b(${digitPart})[jJ]\\b`,
      },
    ],
  };
  const commentType: HighlightMode = {
    begin: lookahead(/# type:/),
    className: 'comment',
    contains: [
      {
        begin: /# type:/,
      },
      {
        begin: /#/,
        end: /\b\B/,
        endsWithParent: true,
      },
    ],
    end: /$/,
    keywords,
  };
  const params: HighlightMode = {
    className: 'params',
    variants: [
      {
        begin: /\(\s*\)/,
        className: '',
        skip: true,
      },
      {
        begin: /\(/,
        contains: [
          { begin: /\bself\b/ },
          prompt,
          number,
          string,
          hljs.HASH_COMMENT_MODE,
        ],
        end: /\)/,
        excludeBegin: true,
        excludeEnd: true,
        keywords,
      },
    ],
  };

  subst.contains = [string, number, prompt];

  return {
    aliases: [...stablePythonAliases],
    contains: [
      prompt,
      number,
      {
        begin: /\bself\b/,
      },
      {
        beginKeywords: 'if',
        relevance: 0,
      },
      string,
      commentType,
      hljs.HASH_COMMENT_MODE,
      {
        contains: [
          hljs.UNDERSCORE_TITLE_MODE,
          params,
          {
            begin: /->/,
            endsWithParent: true,
            keywords,
          },
        ],
        end: /:/,
        illegal: /[${=;\n,]/,
        variants: [
          {
            beginKeywords: 'def',
            className: 'function',
          },
          {
            beginKeywords: 'class',
            className: 'class',
          },
        ],
      },
      {
        begin: /^[\t ]*@/,
        className: 'meta',
        contains: [number, params, string],
        end: /(?=#)|$/,
      },
    ],
    illegal: /(<\/|->|\?)|=>/,
    keywords,
    name: 'Python',
  };
};

export const createCodeBlockLowlight = () => {
  const lowlight = createLowlight(all);

  lowlight.register('python', pythonBrowserSafe);
  lowlight.registerAlias('python', stablePythonAliases);

  return lowlight;
};
